import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
});

/** @type {import('tailwindcss').Config} */
export default {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  theme: {
    extend: {
      colors: {
        arcade: {
          dark: '#070913',
          card: '#0e1326',
          border: '#1f294d',
          neonCyan: '#00f3ff',
          neonPurple: '#a855f7',
          neonPink: '#ec4899',
          neonGreen: '#10b981',
          neonRed: '#ef4444',
          neonYellow: '#f59e0b',
        }
      },
      fontFamily: {
        mono: ['"JetBrains Mono"', 'monospace', 'ui-monospace'],
      }
    },
  },
  plugins: [],
}

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

// Types for QNX RTOS Vision & Arduino Arcade Deck Telemetry

export type ScreenState = 
  | 'ATTRACT' 
  | 'CALIBRATION' 
  | 'STAGE1_TARGET_LOCK' 
  | 'STAGE2_ASTEROID_TUNNEL' 
  | 'RESULTS_CARD';

export interface QNXGazePacket {
  timestampMs: number;       // Deterministic QNX RTOS real-time clock timestamp
  gazeX: number;             // Normalized 0.0 - 1.0 screen coordinates
  gazeY: number;             // Normalized 0.0 - 1.0 screen coordinates
  saccadeDetected: boolean;  // Rapid eye snap detected (<200ms)
  confidence: number;        // Landmark tracking confidence 0-1
}

export interface ArduinoControlPacket {
  timestampMs: number;       // Arduino Uno Q timestamp
  joystickX: number;         // -1.0 to 1.0
  joystickY: number;         // -1.0 to 1.0
  buttonPressed: boolean;    // Tactile arcade fire button
  jitterMagnitude: number;   // Calculated micro-tremor variance
}

export interface TargetEvent {
  id: string;
  spawnTimeMs: number;
  x: number;
  y: number;
  isDecoy: boolean;          // Red flash decoy (ADHD impulse test)
  tEyeHitMs?: number;        // Millisecond eye snapped to target
  tHandHitMs?: number;       // Millisecond joystick trigger pressed
  reactionGapMs?: number;    // t_hand - t_eye
  success: boolean;
}

export interface NeuroMetrics {
  stage1: {
    totalTargets: number;
    hits: number;
    decoyErrors: number;     // False positives (pressed during red decoy)
    avgReactionGapMs: number; // Eye-to-Hand latency
    lastReactionGapMs: number;
    rawGaps: number[];
  };
  stage2: {
    saccadicIntrusions: number; // Jerky catch-up jumps during smooth pursuit
    tremorVariance: number;    // High-frequency jitter index (DCD/Dyspraxia)
    corridorAccuracy: number;  // Path tracking deviation percentage
    smoothPursuitRatio: number;
  };
  finalCard: {
    visualFocusScore: number;    // e.g. 92/100
    eyeToHandLatencyMs: number;  // e.g. 235 ms
    motorSteadinessPct: number;  // e.g. 94%
    cadetRank: string;           // e.g. "Sonic Cadet Master"
    clinicalFlags: {
      impulseControl: 'Normal' | 'Elevated Impulsivity' | 'High Decoy Triggers';
      motorTremor: 'Low Jitter' | 'Mild Intention Tremor' | 'Elevated Jitter';
      visualLatency: 'Sub-200ms Reflex' | 'Typical' | 'Saccadic Delay';
    };
  };
}

export interface HardwareConnectionState {
  qnxConnected: boolean;
  qnxRtosLatencyMs: number;   // QNX deterministic timing jitter (<1ms)
  arduinoConnected: boolean;
  baudRate: number;
  mockMode: boolean;          // For testing without physical hardware
}

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  body {
    background-color: #070913;
    color: #e2e8f0;
    font-family: 'Rajdhani', sans-serif;
    overflow-x: hidden;
  }
}

.font-orbitron {
  font-family: 'Orbitron', monospace;
}

.font-tech {
  font-family: 'Share Tech Mono', monospace;
}

/* CRT Scanline effect for authentic arcade kiosk feel */
.scanlines {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%, 
    rgba(0, 0, 0, 0.25) 50%
  ), linear-gradient(
    90deg,
    rgba(255, 0, 0, 0.03),
    rgba(0, 255, 0, 0.01),
    rgba(0, 0, 255, 0.03)
  );
  background-size: 100% 3px, 6px 100%;
  pointer-events: none;
}

/* 7-Segment Digital Display styling */
.seven-seg {
  font-family: 'Orbitron', monospace;
  text-shadow: 0 0 10px rgba(0, 243, 255, 0.8), 0 0 20px rgba(0, 243, 255, 0.4);
}

.seven-seg-red {
  font-family: 'Orbitron', monospace;
  text-shadow: 0 0 10px rgba(239, 68, 68, 0.8), 0 0 20px rgba(239, 68, 68, 0.4);
}

.neon-glow-cyan {
  box-shadow: 0 0 15px rgba(0, 243, 255, 0.35);
}

.neon-glow-purple {
  box-shadow: 0 0 15px rgba(168, 85, 247, 0.35);
}

.neon-glow-green {
  box-shadow: 0 0 15px rgba(16, 185, 129, 0.35);
}

import React, { createContext, useContext, useState } from 'react';
import { 
  ScreenState, 
  HardwareConnectionState, 
  NeuroMetrics, 
  QNXGazePacket, 
  ArduinoControlPacket 
} from '../types/telemetry';

interface GameContextType {
  currentScreen: ScreenState;
  setScreen: (screen: ScreenState) => void;
  hardware: HardwareConnectionState;
  setHardware: React.Dispatch<React.SetStateAction<HardwareConnectionState>>;
  latestGaze: QNXGazePacket;
  latestControl: ArduinoControlPacket;
  metrics: NeuroMetrics;
  startKioskSession: () => void;
  completeStage1: () => void;
  completeStage2: () => void;
  resetToAttract: () => void;
}

const initialMetrics: NeuroMetrics = {
  stage1: {
    totalTargets: 8,
    hits: 7,
    decoyErrors: 1,
    avgReactionGapMs: 235,
    lastReactionGapMs: 240,
    rawGaps: [260, 245, 230, 240, 225, 250, 235],
  },
  stage2: {
    saccadicIntrusions: 2,
    tremorVariance: 0.06,
    corridorAccuracy: 94,
    smoothPursuitRatio: 0.88,
  },
  finalCard: {
    visualFocusScore: 92,
    eyeToHandLatencyMs: 235,
    motorSteadinessPct: 94,
    cadetRank: 'Sonic Interceptor Specialist',
    clinicalFlags: {
      impulseControl: 'Normal',
      motorTremor: 'Low Jitter',
      visualLatency: 'Sub-200ms Reflex',
    },
  },
};

const GameContext = createContext<GameContextType | undefined>(undefined);

export const GameProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentScreen, setCurrentScreen] = useState<ScreenState>('ATTRACT');

  const [hardware, setHardware] = useState<HardwareConnectionState>({
    qnxConnected: true,
    qnxRtosLatencyMs: 0.42, // Sub-millisecond deterministic QNX clock
    arduinoConnected: true,
    baudRate: 115200,
    mockMode: true,
  });

  const [latestGaze] = useState<QNXGazePacket>({
    timestampMs: Date.now(),
    gazeX: 0.5,
    gazeY: 0.5,
    saccadeDetected: false,
    confidence: 0.98,
  });

  const [latestControl] = useState<ArduinoControlPacket>({
    timestampMs: Date.now(),
    joystickX: 0,
    joystickY: 0,
    buttonPressed: false,
    jitterMagnitude: 0.04,
  });

  const [metrics, setMetrics] = useState<NeuroMetrics>(initialMetrics);

  const startKioskSession = () => {
    setCurrentScreen('STAGE1_TARGET_LOCK');
  };

  const completeStage1 = () => {
    setCurrentScreen('STAGE2_ASTEROID_TUNNEL');
  };

  const completeStage2 = () => {
    setCurrentScreen('RESULTS_CARD');
  };

  const resetToAttract = () => {
    setMetrics(initialMetrics);
    setCurrentScreen('ATTRACT');
  };

  return (
    <GameContext.Provider
      value={{
        currentScreen,
        setScreen: setCurrentScreen,
        hardware,
        setHardware,
        latestGaze,
        latestControl,
        metrics,
        startKioskSession,
        completeStage1,
        completeStage2,
        resetToAttract,
      }}
    >
      {children}
    </GameContext.Provider>
  );
};

export const useGame = () => {
  const context = useContext(GameContext);
  if (!context) {
    throw new Error('useGame must be used within a GameProvider');
  }
  return context;
};

import React from 'react';
import { useGame } from '../../context/GameContext';
import { ScreenState } from '../../types/telemetry';
import { 
  Activity, 
  Cpu, 
  Gamepad2, 
  Eye, 
  Award, 
  Zap, 
  Settings2,
  Compass
} from 'lucide-react';

interface NavbarProps {
  onToggleDebug: () => void;
  debugOpen: boolean;
}

export const Navbar: React.FC<NavbarProps> = ({ onToggleDebug, debugOpen }) => {
  const { currentScreen, setScreen, hardware, metrics } = useGame();

  const screens: { id: ScreenState; label: string; icon: React.ReactNode }[] = [
    { id: 'ATTRACT', label: 'Attract Mode', icon: <Zap className="w-4 h-4" /> },
    { id: 'CALIBRATION', label: 'Calibration', icon: <Compass className="w-4 h-4" /> },
    { id: 'STAGE1_TARGET_LOCK', label: 'Stage 1: Target Lock (15s)', icon: <Eye className="w-4 h-4" /> },
    { id: 'STAGE2_ASTEROID_TUNNEL', label: 'Stage 2: Asteroid Tunnel (15s)', icon: <Gamepad2 className="w-4 h-4" /> },
    { id: 'RESULTS_CARD', label: 'Neuro-Motor Card', icon: <Award className="w-4 h-4" /> },
  ];

  return (
    <header className="border-b border-cyan-900/40 bg-[#090d1e]/90 backdrop-blur-md sticky top-0 z-40 px-4 py-2.5">
      <div className="max-w-7xl mx-auto flex flex-wrap items-center justify-between gap-3">

        {/* Brand & RTOS Status */}
        <div className="flex items-center gap-3">
          <div className="flex items-center justify-center w-10 h-10 rounded-lg bg-cyan-950/80 border border-cyan-500/50 shadow-inner shadow-cyan-500/20">
            <Activity className="w-6 h-6 text-cyan-400 animate-pulse" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="font-orbitron font-bold text-lg tracking-wider text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-sky-300 to-indigo-400">
                AERO NEURO
              </span>
              <span className="text-[10px] font-tech uppercase tracking-widest px-2 py-0.5 rounded bg-cyan-950 border border-cyan-500/40 text-cyan-300">
                QNX RTOS KIOSK
              </span>
            </div>
            <p className="text-xs text-slate-400 font-tech">
              Sub-200ms Pediatric Latency & Tremor Screener
            </p>
          </div>
        </div>

        {/* 7-Segment Reaction Gap Live Feedback HUD */}
        <div className="hidden lg:flex items-center gap-2 bg-[#050813] border border-cyan-500/30 px-3 py-1.5 rounded-md shadow-inner">
          <span className="text-[11px] font-tech text-cyan-400/80 tracking-widest uppercase">
            7-SEG REACTION GAP:
          </span>
          <div className="seven-seg text-cyan-300 font-bold text-lg tracking-wider bg-black/60 px-2 py-0.5 rounded border border-cyan-500/20 min-w-[75px] text-center">
            {metrics.stage1.lastReactionGapMs} <span className="text-xs text-cyan-500">ms</span>
          </div>
          <div className="w-2 h-2 rounded-full bg-cyan-400 animate-ping" />
        </div>

        {/* Hardware Status Badges */}
        <div className="flex items-center gap-2 text-xs font-tech">
          <div className={`flex items-center gap-1.5 px-2.5 py-1 rounded border ${
            hardware.qnxConnected 
              ? 'bg-emerald-950/60 border-emerald-500/40 text-emerald-300' 
              : 'bg-rose-950/60 border-rose-500/40 text-rose-300'
          }`}>
            <Cpu className="w-3.5 h-3.5" />
            <span>RPi 5 (QNX Vision)</span>
            <span className="text-[10px] opacity-75">±{hardware.qnxRtosLatencyMs}ms</span>
          </div>

          <div className={`flex items-center gap-1.5 px-2.5 py-1 rounded border ${
            hardware.arduinoConnected 
              ? 'bg-indigo-950/60 border-indigo-500/40 text-indigo-300' 
              : 'bg-rose-950/60 border-rose-500/40 text-rose-300'
          }`}>
            <Gamepad2 className="w-3.5 h-3.5" />
            <span>Arduino Uno Q (Arcade)</span>
          </div>

          <button
            onClick={onToggleDebug}
            className={`p-1.5 rounded border transition-colors ${
              debugOpen 
                ? 'bg-cyan-500/20 border-cyan-400 text-cyan-300' 
                : 'bg-slate-800/60 border-slate-700 text-slate-400 hover:text-white'
            }`}
            title="Toggle Hardware Telemetry Inspector"
          >
            <Settings2 className="w-4 h-4" />
          </button>
        </div>

      </div>

      {/* Screen Navigation Tabs (Quick Screen Switcher for Testing/Judges) */}
      <div className="max-w-7xl mx-auto mt-2 pt-2 border-t border-slate-800/80 flex items-center justify-between overflow-x-auto gap-2">
        <div className="flex items-center gap-1">
          <span className="text-[11px] font-tech text-slate-400 uppercase mr-1 hidden sm:inline">
            Screens:
          </span>
          {screens.map(screen => (
            <button
              key={screen.id}
              onClick={() => setScreen(screen.id)}
              className={`flex items-center gap-1.5 px-3 py-1 rounded text-xs font-tech uppercase tracking-wider transition-all ${
                currentScreen === screen.id
                  ? 'bg-cyan-500/20 border border-cyan-400 text-cyan-200 shadow-[0_0_12px_rgba(0,243,255,0.25)] font-semibold'
                  : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/50 border border-transparent'
              }`}
            >
              {screen.icon}
              <span>{screen.label}</span>
            </button>
          ))}
        </div>

        {/* Prize Tracks Tagline */}
        <div className="hidden xl:flex items-center gap-2 text-[11px] font-tech text-slate-400">
          <span className="text-amber-400 font-semibold">Hack Western 13:</span>
          <span className="bg-amber-950/40 text-amber-300 px-2 py-0.5 rounded border border-amber-600/30">
            QNX RTOS
          </span>
          <span className="bg-sky-950/40 text-sky-300 px-2 py-0.5 rounded border border-sky-600/30">
            Sun Life Health Hack
          </span>
          <span className="bg-purple-950/40 text-purple-300 px-2 py-0.5 rounded border border-purple-600/30">
            Best Hardware
          </span>
        </div>
      </div>
    </header>
  );
};

import React, { useState, useEffect } from 'react';
import { useGame } from '../../context/GameContext';
import { 
  Eye, 
  Gamepad2, 
  Target, 
  AlertTriangle, 
  Flame, 
  Timer, 
  ArrowRight,
  Crosshair,
  Volume2
} from 'lucide-react';

export const Stage1TargetLock: React.FC = () => {
  const { completeStage1, metrics } = useGame();
  const [timeLeft, setTimeLeft] = useState(15);
  const [targetIndex, setTargetIndex] = useState(1);
  const [targetPos, setTargetPos] = useState({ x: 45, y: 35 });
  const [crosshairPos, setCrosshairPos] = useState({ x: 50, y: 50 });
  const [isDecoy, setIsDecoy] = useState(false);
  const [lastGapMs, setLastGapMs] = useState(240);
  const [hitFeedback, setHitFeedback] = useState<string | null>(null);

  // 15-second game countdown loop framework
  useEffect(() => {
    if (timeLeft <= 0) {
      completeStage1();
      return;
    }
    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft, completeStage1]);

  // Framework action to simulate target acquisition & latency calculation
  const handleSimulateHit = (decoy: boolean) => {
    if (decoy) {
      setHitFeedback('IMPULSE ERROR! Decoy Hit (-50 pts)');
      setTimeout(() => setHitFeedback(null), 1500);
    } else {
      const simulatedTEye = Math.floor(Math.random() * 40 + 110); // ~110-150ms saccade
      const simulatedTHand = Math.floor(Math.random() * 60 + 320); // ~320-380ms hand click
      const gap = simulatedTHand - simulatedTEye;
      setLastGapMs(gap);
      setHitFeedback(`TARGET LOCKED! Eye-to-Hand Gap: ${gap}ms`);
      setTimeout(() => setHitFeedback(null), 1200);

      // Spawn next target
      setTargetIndex(prev => prev + 1);
      setTargetPos({
        x: Math.floor(Math.random() * 60 + 20),
        y: Math.floor(Math.random() * 50 + 25),
      });
      setIsDecoy(Math.random() < 0.25); // 25% chance of decoy
    }
  };

  return (
    <div className="max-w-6xl mx-auto p-4 sm:p-6 space-y-4">

      {/* Top Arcade HUD */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 bg-[#0a0f26]/90 border border-cyan-900/60 p-3 rounded-xl">

        {/* Stage Timer */}
        <div className="flex items-center gap-3 border-r border-slate-800 pr-2">
          <div className="p-2 rounded-lg bg-cyan-950/80 border border-cyan-500/30 text-cyan-400">
            <Timer className="w-5 h-5 animate-spin" />
          </div>
          <div>
            <span className="text-[10px] font-tech text-slate-400 uppercase">TIME REMAINING</span>
            <div className="font-orbitron font-bold text-2xl text-cyan-300">
              {timeLeft}<span className="text-sm font-tech text-cyan-500">s</span>
            </div>
          </div>
        </div>

        {/* Target Count & Impulses */}
        <div className="flex items-center gap-3 border-r border-slate-800 pr-2">
          <div className="p-2 rounded-lg bg-indigo-950/80 border border-indigo-500/30 text-indigo-400">
            <Target className="w-5 h-5" />
          </div>
          <div>
            <span className="text-[10px] font-tech text-slate-400 uppercase">TARGETS ACQUIRED</span>
            <div className="font-orbitron font-bold text-2xl text-indigo-300">
              {targetIndex} <span className="text-xs text-slate-500">/ 10</span>
            </div>
          </div>
        </div>

        {/* 7-Segment Reaction Gap (Live Hardware Feedback) */}
        <div className="flex items-center gap-3 border-r border-slate-800 pr-2">
          <div className="p-2 rounded-lg bg-emerald-950/80 border border-emerald-500/30 text-emerald-400">
            <Flame className="w-5 h-5" />
          </div>
          <div>
            <span className="text-[10px] font-tech text-slate-400 uppercase">7-SEG REACTION GAP</span>
            <div className="seven-seg text-2xl font-bold text-emerald-300">
              {lastGapMs} <span className="text-xs font-tech text-emerald-500">ms</span>
            </div>
          </div>
        </div>

        {/* ADHD Impulse Monitor */}
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-lg bg-rose-950/80 border border-rose-500/30 text-rose-400">
            <AlertTriangle className="w-5 h-5" />
          </div>
          <div>
            <span className="text-[10px] font-tech text-slate-400 uppercase">IMPULSE ERRORS</span>
            <div className="font-orbitron font-bold text-2xl text-rose-300">
              {metrics.stage1.decoyErrors} <span className="text-xs text-slate-500">decoys</span>
            </div>
          </div>
        </div>

      </div>

      {/* Main 15-Second Space Arena / Target Lock Canvas */}
      <div className="relative aspect-[16/9] max-h-[580px] w-full bg-[#050814] rounded-2xl border-2 border-cyan-500/30 overflow-hidden shadow-[0_0_40px_rgba(0,243,255,0.15)] flex items-center justify-center">

        {/* CRT Scanline & Grid Background */}
        <div className="absolute inset-0 scanlines opacity-50"></div>
        <div className="absolute inset-0 opacity-15 bg-[radial-gradient(#00f3ff_1px,transparent_1px)] [background-size:24px_24px]"></div>

        {/* Floating Telemetry Indicator Overlay */}
        <div className="absolute top-4 left-4 z-20 flex flex-col gap-1 text-[11px] font-tech bg-black/60 backdrop-blur-sm border border-cyan-500/20 px-3 py-2 rounded">
          <div className="flex items-center gap-2 text-cyan-400">
            <Eye className="w-3.5 h-3.5" />
            <span>QNX Camera t_eye: <strong className="text-white">124ms</strong></span>
          </div>
          <div className="flex items-center gap-2 text-purple-400">
            <Gamepad2 className="w-3.5 h-3.5" />
            <span>Joystick t_hand: <strong className="text-white">364ms</strong></span>
          </div>
          <div className="text-slate-400 text-[10px]">
            Δt Latency = t_hand - t_eye = <strong className="text-cyan-300">240ms</strong>
          </div>
        </div>

        {/* Decoy Alert Banner */}
        {isDecoy && (
          <div className="absolute top-4 right-4 z-20 flex items-center gap-2 bg-rose-950/80 border border-rose-500/80 px-3 py-1.5 rounded animate-pulse text-rose-300 text-xs font-tech font-bold uppercase tracking-wider">
            <AlertTriangle className="w-4 h-4 text-rose-400" />
            <span>DECOY DETECTED: DO NOT FIRE!</span>
          </div>
        )}

        {/* Hit Feedback Flash Toast */}
        {hitFeedback && (
          <div className="absolute top-1/4 z-30 px-6 py-2 rounded-xl bg-cyan-950/90 border border-cyan-400 text-cyan-200 font-orbitron font-bold text-sm tracking-wide shadow-2xl animate-bounce">
            {hitFeedback}
          </div>
        )}

        {/* Active Target (Alien Target or Decoy) */}
        <div 
          style={{ top: `${targetPos.y}%`, left: `${targetPos.x}%` }}
          className="absolute z-20 -translate-x-1/2 -translate-y-1/2 cursor-pointer transition-all duration-300"
          onClick={() => handleSimulateHit(isDecoy)}
        >
          <div className={`relative flex items-center justify-center w-20 h-20 rounded-full transition-transform active:scale-95 ${
            isDecoy 
              ? 'bg-rose-600/20 border-2 border-rose-500 shadow-[0_0_30px_rgba(244,63,94,0.8)]' 
              : 'bg-cyan-500/20 border-2 border-cyan-400 shadow-[0_0_30px_rgba(0,243,255,0.7)]'
          }`}>
            <div className={`w-8 h-8 rounded-full animate-ping opacity-60 ${isDecoy ? 'bg-rose-500' : 'bg-cyan-400'}`}></div>
            <div className="absolute font-orbitron font-extrabold text-xs text-white">
              {isDecoy ? 'DECOY' : 'TARGET'}
            </div>
          </div>
        </div>

        {/* Joystick Crosshair Simulation */}
        <div 
          style={{ top: `${crosshairPos.y}%`, left: `${crosshairPos.x}%` }}
          className="absolute z-25 -translate-x-1/2 -translate-y-1/2 pointer-events-none transition-all duration-75"
        >
          <div className="relative w-12 h-12 flex items-center justify-center text-cyan-300 opacity-80">
            <Crosshair className="w-12 h-12 animate-pulse" />
          </div>
        </div>

        {/* Arena Controls Prompt */}
        <div className="absolute bottom-4 inset-x-0 flex flex-col items-center gap-2 z-20">
          <p className="text-xs font-tech text-slate-400 bg-black/70 px-4 py-1 rounded-full border border-slate-800">
            Click target above or press physical arcade button to record <span className="text-cyan-300 font-mono">t_hand</span>
          </p>
        </div>

      </div>

      {/* Screen Controls & Testing Shortcuts */}
      <div className="flex flex-wrap items-center justify-between gap-3 pt-2">
        <div className="flex items-center gap-2 text-xs font-tech text-slate-400">
          <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
          <span>QNX Vision Deterministic Eye Tracker active</span>
        </div>

