/* THEME 6: NEON */
body[data-t="6"], .theme-6 {
  --page: #07040d;
  --body: #0d0716;
  --bezel: #5b34b8;
  --scr: #110a1e;
  --fld: #1a1030;
  --ink: #f7eefc;
  --dim: #c1abe3;
  --line: #3b2a5c;
  --a1: #ff5db1;
  --good: #ff5db1;
  --bad: #b99cff;
  --on: #110a1e;
  --dial: #1c1230;
